package com.nigson.experience.lead;

import com.nimbusds.jose.*;import com.nimbusds.jose.crypto.*;import com.nimbusds.jose.jwk.*;import com.nimbusds.jwt.*;import com.nigson.experience.ExperienceApplication;import com.nigson.shared.events.EventCodec;import com.nigson.shared.security.*;import com.sun.net.httpserver.HttpServer;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.interfaces.ECPrivateKey;import java.security.interfaces.RSAPrivateKey;import java.security.interfaces.RSAPublicKey;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.boot.builder.SpringApplicationBuilder;import org.springframework.boot.test.context.TestConfiguration;import org.springframework.boot.web.server.context.WebServerApplicationContext;import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.*;import static org.assertj.core.api.Assertions.*;

class QuoteLeadHttpTest {
 @TestConfiguration(proxyBeanMethods=false) static class LocalCommerce { @Bean @Primary QuoteLeadAssociation.SkuEligibilityPort quoteSkuPort(){return new StatefulQuoteSkuEligibilityMock();} }
 @Test void actualHttpQuoteIntakeAndPrivateQuoteAssociationEnforceActorScopeReplayAndOwnerState()throws Exception{
  String jdbcUrl=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(jdbcUrl!=null,"quote lead HTTP acceptance uses isolated PostgreSQL");var rsaGen=KeyPairGenerator.getInstance("RSA");rsaGen.initialize(2048);var rsa=rsaGen.generateKeyPair();var ecGen=KeyPairGenerator.getInstance("EC");ecGen.initialize(new java.security.spec.ECGenParameterSpec("secp256r1"));var ec=ecGen.generateKeyPair();UUID sku=UUID.randomUUID();var jwks=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);String issuer="http://127.0.0.1:"+jwks.getAddress().getPort()+"/realms/offline";jwks.createContext("/",x->{byte[] b=EventCodec.JSON.writeValueAsBytes(Map.of("keys",List.of(new RSAKey.Builder((RSAPublicKey)rsa.getPublic()).keyID("synthetic").algorithm(JWSAlgorithm.RS256).keyUse(KeyUse.SIGNATURE).build().toJSONObject())));x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);x.close();});jwks.start();
  var props=new HashMap<String,Object>();props.put("APP_ENV","test");props.put("NIGSON_SECURITY_ENABLED","true");props.put("NIGSON_PRODUCT_PHASE","3");props.put("NIGSON_EVENTS_ENABLED","false");props.put("NIGSON_JDBC_URL",jdbcUrl+"?currentSchema=experience");props.put("NIGSON_DB_USER","nigson_experience_app");props.put("NIGSON_DB_PASSWORD","mock-experience-runtime");props.put("NIGSON_OIDC_ISSUER",issuer);props.put("NIGSON_OIDC_JWKS",issuer+"/protocol/openid-connect/certs");props.put("NIGSON_PRIVATE_PEER_CIDRS","127.0.0.1/32");props.put("NIGSON_ACTOR_PUBLIC_KEYS",EventCodec.JSON.writeValueAsString(Map.of("active",Base64.getEncoder().encodeToString(ec.getPublic().getEncoded()))));props.put("NIGSON_LEAD_RECIPIENT_GROUP","synthetic-quote-review");props.put("NIGSON_MESSAGING_INBOUND_ENABLED","true");byte[] phoneHash=new byte[32],phoneCipher=new byte[32],inboundCipher=new byte[32];Arrays.fill(phoneHash,(byte)7);Arrays.fill(phoneCipher,(byte)8);Arrays.fill(inboundCipher,(byte)9);props.put("NIGSON_PHONE_CIPHER_REVISION","synthetic");props.put("NIGSON_PHONE_HASH_KEY_VERSION","1");props.put("NIGSON_PHONE_LOCAL_HASH_KEY",Base64.getEncoder().encodeToString(phoneHash));props.put("NIGSON_PHONE_LOCAL_CIPHER_KEY",Base64.getEncoder().encodeToString(phoneCipher));props.put("NIGSON_INBOUND_LOCAL_CIPHER_KEY",Base64.getEncoder().encodeToString(inboundCipher));props.put("NIGSON_INBOUND_RETENTION_DAYS","30");props.put("NIGSON_TWILIO_ACCOUNT_SID","AC0123456789abcdef0123456789abcdef");props.put("NIGSON_TWILIO_AUTH_TOKEN","synthetic-never-live-auth-token-long-enough");props.put("NIGSON_TWILIO_WHATSAPP_FROM","whatsapp:+2348031234567");props.put("NIGSON_TWILIO_WHATSAPP_PUBLIC_URL","https://callbacks.synthetic.invalid/api/v1/webhooks/notifications/twilio/whatsapp");props.put("server.port","0");props.put("logging.level.root","WARN");UUID party=UUID.randomUUID(),market=UUID.randomUUID(),correlation=UUID.randomUUID();String path="/api/v1/quote-requests",body="{\"marketId\":\""+market+"\",\"products\":[{\"skuId\":\""+sku+"\",\"quantity\":\"2\"}],\"subject\":\"Synthetic request\",\"message\":\"Synthetic message\",\"contact\":{\"name\":\"Synthetic Buyer\",\"email\":\"buyer@example.invalid\"}}",key=UUID.randomUUID().toString();
  try(var app=new SpringApplicationBuilder(ExperienceApplication.class,LocalCommerce.class).properties(props).run();var http=HttpClient.newHttpClient()){
   var state=app.getBean(QuoteLeadAssociation.SkuEligibilityPort.class);((StatefulQuoteSkuEligibilityMock)state).allow(sku,0);String base="http://127.0.0.1:"+((WebServerApplicationContext)app).getWebServer().getPort();String signed=actor(ec,issuer,party,path,correlation,body);var created=send(http,base+path,"POST",body,workload(rsa,issuer,"lead.quote.create_WITH_SIGNED_CUSTOMER"),signed,correlation,key);assertThat(created.statusCode()).withFailMessage(created.body()).isEqualTo(201);var leadId=EventCodec.JSON.readTree(created.body()).path("leadId").asString();var replay=send(http,base+path,"POST",body,workload(rsa,issuer,"lead.quote.create_WITH_SIGNED_CUSTOMER"),signed,correlation,key);assertThat(replay.statusCode()).isEqualTo(201);assertThat(replay.body()).isEqualTo(created.body());assertThat(app.getBean(org.springframework.jdbc.core.JdbcTemplate.class).queryForObject("SELECT count(*) FROM experience.outbox_event WHERE aggregate_id=? AND event_type='lead.created.v1'",Long.class,UUID.fromString(leadId))).isEqualTo(1L);
   String ctx="/internal/v1/leads/"+leadId+"/quote-context";var context=send(http,base+ctx,"GET","",workload(rsa,issuer,"quote.read"),null,UUID.randomUUID(),null);assertThat(context.statusCode()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(context.body()).path("partyId").asString()).isEqualTo(party.toString());UUID quote=UUID.randomUUID(),command=UUID.randomUUID();String assoc="/internal/v1/leads/"+leadId+"/quote-association",associationBody=EventCodec.JSON.writeValueAsString(Map.of("commandId",command,"quoteId",quote,"quoteState","DRAFT"));var ack=send(http,base+assoc,"POST",associationBody,workload(rsa,issuer,"quote.write"),null,UUID.randomUUID(),command.toString());assertThat(ack.statusCode()).isEqualTo(200);assertThat(ack.body()).isEqualTo(send(http,base+assoc,"POST",associationBody,workload(rsa,issuer,"quote.write"),null,UUID.randomUUID(),command.toString()).body());
   var denied=send(http,base+path,"POST",body,workload(rsa,issuer,"quote.read"),signed,UUID.randomUUID(),UUID.randomUUID().toString());assertThat(denied.statusCode()).isIn(401,403);
  }finally{jwks.stop(0);}
 }
 private static String workload(KeyPair rsa,String issuer,String scope)throws Exception{var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.RS256).keyID("synthetic").build(),new JWTClaimsSet.Builder().issuer(issuer).subject("synthetic-workload").audience("nigson-experience").claim("typ","Bearer").claim("client_id","nigson-commerce").claim("azp","nigson-commerce").claim("scope",scope).issueTime(new Date()).expirationTime(Date.from(Instant.now().plusSeconds(120))).build());jwt.sign(new RSASSASigner((RSAPrivateKey)rsa.getPrivate()));return jwt.serialize();}
 private static String actor(KeyPair ec,String issuer,UUID party,String path,UUID corr,String body)throws Exception{var actor=new ActorAssertion.Actor(party,issuer,"synthetic-user",null,Set.of("CUSTOMER"),Set.of("lead.quote.create_WITH_SIGNED_CUSTOMER"),null);var binding=new ActorAssertion.Binding("experience","lead.quote.create_WITH_SIGNED_CUSTOMER","POST",path,corr,ActorAssertion.Binding.bodyHash(body.getBytes(StandardCharsets.UTF_8)));var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.ES256).keyID("active").type(new JOSEObjectType("nigson-actor+jwt")).build(),ActorAssertion.claims(actor,binding,Instant.now()));jwt.sign(new ECDSASigner((ECPrivateKey)ec.getPrivate()));return jwt.serialize();}
 private static HttpResponse<String> send(HttpClient http,String url,String method,String body,String bearer,String actor,UUID corr,String key)throws Exception{var b=HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(10)).header("X-Correlation-ID",corr.toString()).header("Authorization","Bearer "+bearer);if(actor!=null)b.header("X-Nigson-Actor",actor);if(key!=null)b.header("Idempotency-Key",key);if(!method.equals("GET"))b.header("Content-Type","application/json");return http.send(b.method(method,body.isEmpty()?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
}
